const r=JSON.parse(load("shakerRead").content[0].text); const frac=s=>s.split("/").reduce((a,b)=>a/b); const ns=r.data.document.split("\n").filter(l=>l.startsWith("EVENT")).map(l=>{const p=l.split(" ");return {id:p[1],at:frac(p[3]),cell:Math.round(frac(p[3])*512),velocity:+p[6]}}); store("notes",ns);
text(Array.from({length:8},(_,bar)=>({bar:bar+1,offsets:ns.slice(bar*8,bar*8+8).map((n,j)=>n.cell-(bar*8+j)*256)})));
text(ALL_TOOLS.filter(x=>/mcp__ghostnote__.*(transport|scene|launcher)/.test(x.name)).map(x=>({name:x.name,description:x.description.slice(0,180)})));

const r=JSON.parse(load("shakerRead").content[0].text), ns=load("notes");
const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);const f=c=>{const g=gcd(c,512);return `${c/g}${512/g===1?"":"/"+512/g}`};
const tpl=[0,39,9,50,12,34,-3,47,0,39,9,50,12,34,-11,-25];
const overlays=(n,i,suffix,at)=>{const nom="nom_"+n.id+"_"+suffix, gro="gro_"+n.id+"_"+suffix;const depends={events:[{id:n.id,fields:["clip","at","duration"]}],clips:[],overlays:[],membership:[]};const provenance={kind:"inferred",source:"Scene 1 shaker",method:"Repeated two-bar eighth-note pattern; bar drift separated from recurring step offsets; source observed at 1/512-beat resolution"};return [
{id:nom,type:"nominal",state:"current",provenance,depends,data:{event:n.id,at:f(i*256),duration:"1/16",division:"1/2"}},
{id:gro,type:"groove",state:"current",provenance,depends:{...depends,overlays:[nom]},data:{event:n.id,nominal:nom,intent:"unresolved",phase:"0",template:f(tpl[i%16]),cross:"0",local:"0",unassigned:f(at-i*256-tpl[i%16]),durationIntent:"0",durationUnassigned:"0",sourceAt:f(at),sourceDuration:"1/16",atDelta:"0",durationDelta:"0"}}]};
store("makeOverlaySpec",{tpl}); store("originalOverlays",ns.flatMap((n,i)=>overlays(n,i,"before",n.cell)));
const shifts=[0,7,-5,10,-3,5,-7,3]; const adjusted=ns.map((n,i)=>({...n,newCell:n.cell-(Math.abs(shifts[Math.floor(i/8)])>=4?shifts[Math.floor(i/8)]:0)}));store("adjusted",adjusted);store("afterOverlays",adjusted.flatMap((n,i)=>overlays(n,i,"clean",n.newCell))); store("fractionFn",""); 
const doc="DOC ghostnote-document 1.0 patch\nBASE "+JSON.stringify(r.authority.base)+"\nFIELDS id clip at duration pitch velocity channel mute\n"+load("originalOverlays").map(x=>"OVERLAY_PUT "+JSON.stringify(x)).join("\n");
text(await tools.mcp__ghostnote__edit_launcher_clip({trackId:"b02a493a-05fe-4707-a39f-467c8ed8b20e",row:0,document:doc,readback:"summary"})); store("baselineDone",true);

