const r=JSON.parse(load("looseRead").content[0].text);
const frac=s=>{const p=s.split("/").map(Number);return p.length===1?p[0]:p[0]/p[1]};
const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);const f=c=>{const g=gcd(c,512);return `${c/g}${512/g===1?"":"/"+512/g}`};
const claims=r.data.document.split("\n").filter(l=>l.startsWith("OVERLAY ")).map(l=>JSON.parse(l.slice(8)));
const originals=new Map(load("notes").map(n=>[n.id,n.cell]));
const ns=r.data.document.split("\n").filter(l=>l.startsWith("EVENT ")).map(l=>{const p=l.split(" ");return {id:p[1],cell:Math.round(frac(p[3])*512)}});
const changed=ns.map(n=>({...n,target:n.cell+Math.round((originals.get(n.id)-n.cell)/3)})).filter(n=>n.target!==n.cell);
let lines=["DOC ghostnote-document 1.0 patch","BASE "+JSON.stringify(r.authority.base),"FIELDS id clip at duration pitch velocity channel mute"];
for(const n of changed){
lines.push("UPDATE "+n.id+" "+JSON.stringify({at:f(n.target)}));
const nom=claims.find(x=>x.type==="nominal"&&x.state==="current"&&x.data.event===n.id);
const gro=claims.find(x=>x.type==="groove"&&x.state==="current"&&x.data.event===n.id);
const nextNom=JSON.parse(JSON.stringify(nom));delete nextNom.basis;nextNom.id="nom_"+n.id+"_relaxed";
const nextGro=JSON.parse(JSON.stringify(gro));delete nextGro.basis;nextGro.id="gro_"+n.id+"_relaxed";nextGro.depends.overlays=[nextNom.id];nextGro.data.nominal=nextNom.id;nextGro.data.sourceAt=f(n.target);nextGro.data.unassigned=f(Math.round(frac(gro.data.unassigned)*512)+n.target-n.cell);
nextGro.provenance.method="Restore one third of previously removed bar drift, rounded to 1/512 beat; preserve recurring two-bar timing template";
lines.push("OVERLAY_PUT "+JSON.stringify(nextNom),"OVERLAY_PUT "+JSON.stringify(nextGro));
}
store("relaxedPatch",lines.join("\n"));text({changed:changed.length,barOffsetsRestored:[...new Set(changed.map(n=>n.target-n.cell))]});
const result=await tools.mcp__ghostnote__edit_launcher_clip({trackId:"b02a493a-05fe-4707-a39f-467c8ed8b20e",row:0,document:lines.join("\n"),readback:"summary"});
store("relaxedResult",result);text(result);

